{
  "name": "workspace-safety-hooks",
  "version": "1.0.0",
  "description": "Project-local safety hooks for destructive commands"
}
EOF
cat > /workspace/hooks.json <<'EOF'
{
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Bash",
        "hooks": [
          {
            "type": "command",
            "command": "./scripts/warn-on-rm-rf.sh"
          }
        ]
      }
    ]
  }
}
EOF
cat > /workspace/scripts/warn-on-rm-rf.sh <<'EOF'
#!/usr/bin/env bash
set -euo pipefail

input="${HOOKIFY_INPUT:-}"
if [[ -z "$input" ]]; then
  exit 0
fi

if [[ "$input" == *"rm -rf"* ]]; then
  printf 'Warning: this Bash command contains rm -rf. Proceed carefully.\n' >&2
fi
EOF
chmod +x /workspace/scripts/warn-on-rm-rf.sh

mkdir -p /workspace/.codex/hooks && cat > /workspace/.codex/hooks/block-env-writes.sh <<'EOF'
#!/usr/bin/env bash
set -euo pipefail

payload="${1:-}"

if printf '%s' "$payload" | rg -n '(^|["\''[:space:]/\\])\.env(\.[^"\''[:space:]/\\]+)?($|["\''[:space:]/\\])' >/dev/null; then
  echo 'Blocked: writes to .env files are not allowed.' >&2
  exit 1
fi

exit 0
EOF
chmod +x /workspace/.codex/hooks/block-env-writes.sh
cat > /workspace/.codex/hookify.env.json <<'EOF'
{
  "rules": [
    {
      "name": "block-env-writes",
      "description": "Block any Edit or Write touching .env files",
      "match": {
        "operations": ["Edit", "Write"],
        "paths": [".env", ".env.*", "**/.env", "**/.env.*"]
      },
      "action": {
        "type": "deny",
        "message": "Writes to .env files are blocked to protect secrets."
      }
    }
  ]
}
EOF
printf 'Created:\n'; sed -n '1,120p' /workspace/.codex/hookify.env.json

